  "Bacarıq xəritən": { en: "Your skill map", ru: "Твоя карта навыков" }, "Gücün haradadır?": { en: "Where are your strengths?", ru: "В чём твоя сила?" }, "Bacarıqların radar qrafiki": { en: "Skills radar chart", ru: "Радарная диаграмма навыков" }, "Komanda": { en: "Teamwork", ru: "Командная работа" }, "Liderlik": { en: "Leadership", ru: "Лидерство" }, "Təqdimat": { en: "Presentation", ru: "Презентация" }, "⚙ Robot qur": { en: "⚙ Build a robot", ru: "⚙ Собери робота" }, "✦ Dizayn yarat": { en: "✦ Create a design", ru: "✦ Создай дизайн" }, "◎ Komandaya qoşul": { en: "◎ Join a team", ru: "◎ Присоединяйся к команде" }, "↗ Fikrini paylaş": { en: "↗ Share your idea", ru: "↗ Поделись идеей" }, "Bacarıq göstəriciləri": { en: "Skill indicators", ru: "Показатели навыков" },
  "Valideyn paneli · demo": { en: "Parent dashboard · demo", ru: "Кабинет родителя · демо" }, "İnkişaf bir baxışda": { en: "Growth at a glance", ru: "Развитие с первого взгляда" }, "iştirak günü": { en: "days attended", ru: "дней участия" }, "tamamlanan layihə": { en: "completed projects", ru: "завершённых проектов" }, "bu ay inkişaf": { en: "growth this month", ru: "рост за этот месяц" }, "Komanda işi": { en: "Teamwork", ru: "Работа в команде" }, "Son fəaliyyət": { en: "Latest activity", ru: "Последняя активность" }, "“İşıqlı şəhər” maketi": { en: "“Bright City” model", ru: "Макет «Светлый город»" }, "Komanda günəş enerjisi ilə işləyən işıq sisteminin ilk prototipini təqdim etdi. Növbəti mərhələ: hərəkət sensoru əlavə etmək.": { en: "The team presented the first prototype of a solar-powered lighting system. Next step: add a motion sensor.", ru: "Команда представила первый прототип световой системы на солнечной энергии. Следующий шаг — добавить датчик движения." },
  "Tədbir təqvimi": { en: "Event calendar", ru: "Календарь событий" }, "Əvvəlki ay": { en: "Previous month", ru: "Предыдущий месяц" }, "Növbəti ay": { en: "Next month", ru: "Следующий месяц" }, "Tədbir seçərək qısa proqramı gör.": { en: "Choose an event to see its short programme.", ru: "Выберите событие, чтобы увидеть краткую программу." },
  "Coolab AI bələdçisi · demo": { en: "Coolab AI guide · demo", ru: "ИИ-помощник Coolab · демо" }, "13 yaş, robotları sevirəm": { en: "I'm 13 and I love robots", ru: "Мне 13, я люблю роботов" }, "Dizayna necə başlayım?": { en: "How do I start with design?", ru: "Как начать заниматься дизайном?" }, "Düşərgədə nə edəcəyəm?": { en: "What will I do at camp?", ru: "Что я буду делать в лагере?" }, "Salam! Mən Coolab bələdçisiyəm. Səni ən çox nə maraqlandırır?": { en: "Hi! I'm the Coolab guide. What interests you most?", ru: "Привет! Я помощник Coolab. Что тебе интереснее всего?" }, "Mesajın": { en: "Your message", ru: "Ваше сообщение" }, "Məsələn: Mən oyun yaratmaq istəyirəm": { en: "For example: I want to make a game", ru: "Например: я хочу создать игру" },
  "Uşağın gələcəyini yalnız dərs yox, təcrübə formalaşdırır.": { en: "A child's future is shaped not only by lessons, but by experience.", ru: "Будущее ребёнка формируют не только уроки, но и опыт." }, "Coolab School haqqında ətraflı oxu": { en: "Read more about Coolab School", ru: "Подробнее о Coolab School" }, "Coolab uşaqlara maraqlarını kəşf etmək, seçdikləri sahədə inkişaf etmək və biliklərini real layihələrdə sınamaq üçün mühit yaradır.": { en: "Coolab creates a place for children to explore their interests, develop in a chosen field and test their knowledge in real projects.", ru: "Coolab создаёт среду, где дети исследуют интересы, развиваются в выбранной сфере и проверяют знания в реальных проектах." },
  "7 aylıq proqram: həftədə 2 dəfə, hər dərs 2 saat. Elektronika, mexanika və proqramlaşdırma.": { en: "Seven-month programme: twice a week, two hours per lesson. Electronics, mechanics and programming.", ru: "Семимесячная программа: два раза в неделю, по два часа. Электроника, механика и программирование." }, "Həftədə 2 dəfə, hər dərs 2 saat. Rəng, kompozisiya və vizual hekayə ilə işləyin.": { en: "Twice a week, two hours per lesson. Work with colour, composition and visual storytelling.", ru: "Два раза в неделю, по два часа. Работа с цветом, композицией и визуальным рассказом." }, "1 ay ərzində AI əsasları, araşdırma, ideya yaratma və müasir alətlərdən yaradıcı istifadə.": { en: "One month of AI basics, research, idea generation and creative use of modern tools.", ru: "Один месяц основ ИИ, исследований, создания идей и творческого использования современных инструментов." }, "HTML, CSS və veb məhsul yaratma məntiqini real layihələrlə öyrənin.": { en: "Learn the logic of building web products with HTML and CSS through real projects.", ru: "Изучайте создание веб-продуктов с HTML и CSS на реальных проектах." }, "Hər şənbə 11:00–17:00: mentor saatı, oyunlar, müzakirələr və komanda fəaliyyəti.": { en: "Every Saturday, 11:00–17:00: mentor time, games, discussions and team activities.", ru: "Каждую субботу, 11:00–17:00: время с менторами, игры, обсуждения и командные активности." }, "4 fəsil düşərgə": { en: "Four-season camp", ru: "Лагерь четырёх сезонов" }, "İlboyu təhsil, yaradıcılıq, oyun və sosial təcrübəni birləşdirən düşərgələr.": { en: "Camps combining learning, creativity, games and social experiences throughout the year.", ru: "Лагеря, объединяющие обучение, творчество, игры и социальный опыт круглый год." },
  "Bütün fəaliyyətləri və detalları gör": { en: "See all activities and details", ru: "Посмотреть все активности и детали" }, "Düşərgədən daha artığı": { en: "More than camp", ru: "Больше, чем лагерь" }, "Coolab təcrübəsi": { en: "The Coolab experience", ru: "Опыт Coolab" }, "Əyləncənin içində real inkişaf.": { en: "Real growth through fun.", ru: "Настоящее развитие через игру." }, "Komanda ilə işləmək": { en: "Working in a team", ru: "Работа в команде" }, "Problemə yaradıcı yanaşmaq": { en: "Creative problem solving", ru: "Творческий подход к задачам" }, "Məsuliyyət və liderlik": { en: "Responsibility and leadership", ru: "Ответственность и лидерство" }, "Öz fikrini inamla təqdim etmək": { en: "Presenting your ideas with confidence", ru: "Уверенная презентация своих идей" },
