  "Coolab inkişaf xəritəsi": { en: "Coolab growth map", ru: "Карта развития Coolab" },
  "Robototexnika proqramı iştirakçısı · ilk müstəqil layihəsinə doğru irəliləyir.": { en: "Robotics programme participant · progressing towards his first independent project.", ru: "Участник программы по робототехнике · движется к своему первому самостоятельному проекту." },
  "Mahirın inkişaf yolu": { en: "Mahir's growth journey", ru: "Путь развития Махира" },
  "Başlanğıc": { en: "Starting point", ru: "Начало" }, "Öyrəndi": { en: "Learned", ru: "Освоил" }, "Yaratdı": { en: "Created", ru: "Создал" },
  "Robototexnika sahəsində əvvəlcədən layihə təcrübəsi yox idi.": { en: "He had no previous project experience in robotics.", ru: "У него не было опыта проектов в робототехнике." },
  "Elektronika, sensorlar və LED-lərlə işləmə məntiqini sınaqdan keçirdi.": { en: "He explored the principles of working with electronics, sensors and LEDs.", ru: "Он изучил принципы работы с электроникой, датчиками и LED." },
  "Səs sensoru ilə idarə olunan LED sistemini müstəqil şəkildə qurdu.": { en: "He independently built an LED system controlled by a sound sensor.", ru: "Он самостоятельно собрал LED-систему, управляемую датчиком звука." },
  "Robototexnika proqramına başlamazdan əvvəl Mahir bu sahədə heç bir layihə hazırlamamışdı. Proqramın sonunda isə öyrəndiyi bilikləri tətbiq edərək müstəqil layihələr qurdu.": { en: "Before starting the robotics programme, Mahir had not created a project in this field. By the end of the programme, he applied what he learned to build independent projects.", ru: "До начала программы по робототехнике Махир не создавал проектов в этой сфере. К концу программы он применил полученные знания и собрал самостоятельные проекты." },
  "Elektronika əsasları": { en: "Electronics fundamentals", ru: "Основы электроники" }, "Sensor məntiqi": { en: "Sensor logic", ru: "Логика датчиков" }, "LED idarəetməsi": { en: "LED control", ru: "Управление LED" }, "Prototipləşdirmə": { en: "Prototyping", ru: "Прототипирование" }, "Müstəqil problem həlli": { en: "Independent problem-solving", ru: "Самостоятельное решение задач" }, "Layihə təqdimatı": { en: "Project presentation", ru: "Презентация проекта" },
  "Qazandı": { en: "Acquired", ru: "Освоил" }, "Güclənir": { en: "Growing", ru: "Развивается" },
  "Seçilmiş layihə: Səs sensoru ilə LED sistemi": { en: "Featured project: Sound-sensor LED system", ru: "Избранный проект: LED-система с датчиком звука" },
  "Layihənin ideyası:": { en: "Project idea:", ru: "Идея проекта:" },
  "səsi qəbul edən sensor vasitəsilə LED işıqların idarə olunması. Mahir öyrəndiyi bilikləri birləşdirərək işlək prototip hazırlayıb və layihəsini təqdim edib.": { en: "controlling LED lights with a sensor that detects sound. Mahir combined what he learned to make a working prototype and present his project.", ru: "управление LED-огнями с помощью датчика, реагирующего на звук. Махир объединил полученные знания, подготовил работающий прототип и представил свой проект." },
  "Coolab mağazası": { en: "Coolab store", ru: "Магазин Coolab" }, "Kurs, düşərgə və yaradıcı məhsulları bir yerdən seçin.": { en: "Choose courses, camps and creative products in one place.", ru: "Выбирайте курсы, лагеря и творческие товары в одном месте." }, "Səbətinizə əlavə edin, sifarişi yaradın və yerli ödəniş sistemi qoşulduqda təhlükəsiz ödənişə keçin.": { en: "Add items to your cart, create an order and proceed to secure payment once a local provider is connected.", ru: "Добавляйте товары в корзину, создавайте заказ и переходите к безопасной оплате после подключения местного провайдера." }, "Mağaza yüklənir…": { en: "Loading store…", ru: "Загрузка магазина…" }, "Hazırda satışda məhsul yoxdur.": { en: "There are no products on sale right now.", ru: "Сейчас в продаже нет товаров." }, "Coolab proqramı və ya məhsulu.": { en: "A Coolab programme or product.", ru: "Программа или товар Coolab." }, "Qeydiyyat açıqdır": { en: "Registration is open", ru: "Регистрация открыта" }, "yer qalıb": { en: "spots left", ru: "мест осталось" }, "Stokda yoxdur": { en: "Out of stock", ru: "Нет в наличии" }, "Səbətə əlavə et": { en: "Add to cart", ru: "Добавить в корзину" }, "Daxil olun": { en: "Sign in", ru: "Войти" }, "Səbətim": { en: "My cart", ru: "Моя корзина" }, "Səbəti yaratmaq və sifarişi izləmək üçün hesabınıza daxil olun.": { en: "Sign in to create a cart and track your order.", ru: "Войдите, чтобы создать корзину и отслеживать заказ." }, "Səbətiniz hələ boşdur.": { en: "Your cart is empty.", ru: "Ваша корзина пока пуста." }, "Səbətdən sil": { en: "Remove from cart", ru: "Удалить из корзины" }, "Cəmi": { en: "Total", ru: "Итого" }, "Sifarişi yarat": { en: "Create order", ru: "Создать заказ" }, "Səbətdən istifadə etmək üçün hesabınıza daxil olun.": { en: "Sign in to use the cart.", ru: "Войдите, чтобы использовать корзину." }, "Sorğu tamamlanmadı.": { en: "Request could not be completed.", ru: "Не удалось выполнить запрос." }, "Sifariş": { en: "Order", ru: "Заказ" }, "Stok sayı (boş = limitsiz)": { en: "Stock quantity (blank = unlimited)", ru: "Количество на складе (пусто = без ограничений)" }, "Limitsiz stok": { en: "Unlimited stock", ru: "Неограниченный запас" },
