const originalTextNodes = new WeakMap();
const originalAttributes = new WeakMap();
const originalDocumentTitle = document.title;

const translateSource = (source) => sourceMessages[source]?.[locale] ?? source;

const applySourceTranslations = () => {
  document.title = translateSource(originalDocumentTitle);
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const parent = node.parentElement;
      if (!parent || ["SCRIPT", "STYLE", "NOSCRIPT"].includes(parent.tagName)) return NodeFilter.FILTER_REJECT;
      if (parent.closest("[data-i18n]")) return NodeFilter.FILTER_REJECT;
      return node.nodeValue.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
    },
  });
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach((node) => {
    const original = originalTextNodes.get(node) ?? node.nodeValue;
    originalTextNodes.set(node, original);
    const trimmed = original.trim();
    const translated = translateSource(trimmed);
    node.nodeValue = translated === trimmed ? original : original.replace(trimmed, translated);
  });
  document.querySelectorAll("[placeholder], [title], [aria-label]").forEach((element) => {
    const original = originalAttributes.get(element) ?? {
      placeholder: element.getAttribute("placeholder"), title: element.getAttribute("title"), ariaLabel: element.getAttribute("aria-label"),
    };
    originalAttributes.set(element, original);
    if (original.placeholder) element.setAttribute("placeholder", translateSource(original.placeholder));
    if (original.title) element.setAttribute("title", translateSource(original.title));
    if (original.ariaLabel) element.setAttribute("aria-label", translateSource(original.ariaLabel));
  });
};

let locale = supportedLocales.includes(localStorage.getItem(storageKey))
  ? localStorage.getItem(storageKey)
  : "az";

const translate = (key, fallback = key) => messages[locale]?.[key] ?? messages.az[key] ?? fallback;

const installStyles = () => {
  if (document.querySelector("#coolab-language-styles")) return;
  const style = document.createElement("style");
  style.id = "coolab-language-styles";
  style.textContent = `.coolab-language{display:inline-flex;align-items:center;gap:2px;padding:4px;border:1px solid rgba(185,223,239,.4);border-radius:12px;background:rgba(255,255,255,.1)}.coolab-language button{min-width:30px;height:29px;padding:0 7px;border:0;border-radius:8px;color:inherit;background:transparent;font:800 .7rem/1 Inter,system-ui,sans-serif;cursor:pointer}.coolab-language button:hover{background:rgba(16,185,208,.16)}.coolab-language button.is-active{color:#fff;background:#087ec4;box-shadow:0 4px 9px rgba(7,59,112,.18)}.site-header .coolab-language{color:#e8f6fb}.topbar .coolab-language{color:#073b70;background:#f2f9fc}@media(max-width:700px){.coolab-language button{min-width:27px;padding:0 5px}.nav .coolab-language{order:4}}`;
  document.head.append(style);
};

const addSwitcher = () => {
  if (document.querySelector(".coolab-language")) return;
  const switcher = document.createElement("div");
  switcher.className = "coolab-language";
  switcher.setAttribute("role", "group");
  switcher.setAttribute("aria-label", translate("language.label"));
  supportedLocales.forEach((code) => {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = code.toUpperCase();
    button.dataset.locale = code;
    button.title = code === "az" ? "Azərbaycan dili" : code === "en" ? "English" : "Русский";
    button.addEventListener("click", () => setLocale(code));
    switcher.append(button);
  });
  const authActions = document.querySelector(".auth-actions");
  const profile = document.querySelector(".profile-mini");
  const nav = document.querySelector(".nav");
  if (authActions?.parentElement) authActions.parentElement.insertBefore(switcher, authActions);
  else if (profile?.parentElement) profile.parentElement.insertBefore(switcher, profile);
  else if (nav) nav.append(switcher);
  else if (document.querySelector(".sales-nav nav")) document.querySelector(".sales-nav nav").append(switcher);
};

const applyLocale = (emitChange = false) => {
  document.documentElement.lang = locale;
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const message = translate(element.dataset.i18n, element.textContent);
    element.textContent = message;
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((element) => {
    element.placeholder = translate(element.dataset.i18nPlaceholder, element.placeholder);
  });
  document.querySelectorAll("[data-i18n-aria]").forEach((element) => {
    element.setAttribute("aria-label", translate(element.dataset.i18nAria, element.getAttribute("aria-label") || ""));
  });
  applySourceTranslations();
  document.querySelectorAll(".coolab-language").forEach((switcher) => {
    switcher.setAttribute("aria-label", translate("language.label"));
    switcher.querySelectorAll("button").forEach((button) => {
      const active = button.dataset.locale === locale;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-pressed", String(active));
    });
  });
  if (emitChange) document.dispatchEvent(new CustomEvent("coolab:localechange", { detail: { locale } }));
};

const setLocale = (nextLocale) => {
  if (!supportedLocales.includes(nextLocale)) return;
  locale = nextLocale;
  localStorage.setItem(storageKey, locale);
  applyLocale(true);
};

window.CoolabI18n = { get locale() { return locale; }, t: translate, source: translateSource, refresh: () => applyLocale(false), setLocale };
installStyles();
addSwitcher();
applyLocale(false);
